begin;
create temp table f(k text primary key,id uuid default gen_random_uuid());
insert into f(k) values('owner'),('editor'),('contributor'),('outsider'),('viewer'),('w'),('other'),('a'),('r'),('c'),('s'),('x');
create temp table results(test text,result text);
grant select on f to authenticated;grant select,insert on results to authenticated;
create function pg_temp.ok(v boolean,n text) returns void language plpgsql as $$begin if not coalesce(v,false) then raise exception 'FAIL %',n;end if;insert into results values(n,'PASS');end$$;
create function pg_temp.no(q text,fragment text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if position(fragment in sqlerrm)=0 then raise exception 'Unexpected error %: %',n,sqlerrm;end if;insert into results values(n,'PASS');return;end;raise exception 'FAIL forbidden operation succeeded %',n;end$$;
create function pg_temp.as_user(n text) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from f where k=n),'email','runctrl-test-'||n||'@example.invalid','role','authenticated')::text,true)::text::void$$;
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) select id,'runctrl-test-'||k||'@example.invalid','{"provider":"email"}'::jsonb,'{}'::jsonb from f where k in ('owner','editor','contributor','outsider','viewer');
insert into rc_workspaces(id,slug,name) select id,'test-'||id,'TEST RUNCTRL rollback fixture' from f where k in ('w','other');
insert into rc_members(workspace_id,user_id,role) select w.id,u.id,u.k from f w,f u where w.k='w' and u.k in ('owner','editor','contributor','viewer');
insert into rc_members(workspace_id,user_id,role) select w.id,u.id,'owner' from f w,f u where w.k='other' and u.k='outsider';
set local role authenticated;
select pg_temp.as_user('outsider');
insert into rc_access_requests(id,workspace_id,user_id,email) select r.id,w.id,u.id,'runctrl-test-outsider@example.invalid' from f r,f w,f u where r.k='r' and w.k='w' and u.k='outsider';
select pg_temp.ok(not exists(select 1 from rc_members where workspace_id=(select id from f where k='w')),'pending access grants no membership');
select pg_temp.no($q$insert into rc_members(workspace_id,user_id,role) select w.id,u.id,'owner' from f w,f u where w.k='w' and u.k='outsider'$q$,'row-level security','outsider cannot self-elevate');
select pg_temp.no($q$select rc_resolve_access((select id from f where k='r'),'approved')$q$,'Owner access required','requester cannot approve access');
select pg_temp.as_user('owner');
select rc_resolve_access((select id from f where k='r'),'approved');
select pg_temp.ok((select status='approved' and resolved_at is not null from rc_access_requests where id=(select id from f where k='r')),'owner resolves request');
select pg_temp.ok((select role='contributor' from rc_members where workspace_id=(select id from f where k='w') and user_id=(select id from f where k='outsider')),'approval grants requested role');
select pg_temp.no($q$select rc_resolve_access((select id from f where k='r'),'approved')$q$,'already resolved','resolution replay blocked');
select pg_temp.as_user('contributor');
insert into rc_assignments(id,workspace_id,title,assigned_to,created_by) select a.id,w.id,'TEST assignment',u.id,u.id from f a,f w,f u where a.k='a' and w.k='w' and u.k='contributor';
select pg_temp.no($q$insert into rc_assignments(workspace_id,title,assigned_to,created_by,status) select w.id,'TEST bypass',u.id,u.id,'approved' from f w,f u where w.k='w' and u.k='contributor'$q$,'row-level security','contributor cannot approve own assignment');
select pg_temp.as_user('editor');
update rc_assignments set status='assigned' where id=(select id from f where k='a');
select pg_temp.ok((select status='assigned' from rc_assignments where id=(select id from f where k='a')),'editor updates assignment');
select pg_temp.no($q$update rc_assignments set assigned_to=(select id from f where k='viewer') where id=(select id from f where k='a')$q$,'Assignee must','viewer assignment blocked');
select pg_temp.no($q$update rc_assignments set credential_status='granted' where id=(select id from f where k='a')$q$,'derived','credential status spoof blocked');
select pg_temp.no($q$insert into rc_credentials(assignment_id,workspace_id,approval_at) select a.id,w.id,now() from f a,f w where a.k='a' and w.k='w'$q$,'unapproved drafts','forged approval insert blocked');
insert into rc_credentials(id,assignment_id,workspace_id,contact_email,request_notes) select c.id,a.id,w.id,'host@example.invalid','TEST internal request scope' from f c,f a,f w where c.k='c' and a.k='a' and w.k='w';
select pg_temp.no($q$update rc_credentials set status='granted',proof_url='https://example.invalid/proof' where id=(select id from f where k='c')$q$,'Invalid credential','skip authorization blocked');
update rc_credentials set status='approval_required' where id=(select id from f where k='c');
select pg_temp.no($q$update rc_credentials set status='authorized' where id=(select id from f where k='c')$q$,'Only workspace owner','editor authorization blocked');
select pg_temp.as_user('owner');
update rc_credentials set status='authorized' where id=(select id from f where k='c');
select pg_temp.ok((select approval_by=auth.uid() and approval_at is not null from rc_credentials where id=(select id from f where k='c')),'owner authorization recorded');
select pg_temp.ok((select credential_status='authorized' from rc_assignments where id=(select id from f where k='a')),'assignment credential status synchronized');
select pg_temp.no($q$update rc_credentials set contact_email='changed@example.invalid' where id=(select id from f where k='c')$q$,'Return to draft','approved request details locked');
select pg_temp.no($q$update rc_credentials set approval_at=now()+interval '1 day' where id=(select id from f where k='c')$q$,'server controlled','approval evidence immutable');
select pg_temp.no($q$update rc_credentials set status='sent' where id=(select id from f where k='c')$q$,'evidence required','sent status needs evidence');
update rc_credentials set status='draft' where id=(select id from f where k='c');
select pg_temp.ok((select approval_at is null and approval_by is null from rc_credentials where id=(select id from f where k='c')),'draft reset clears approval');
select pg_temp.as_user('contributor');
insert into rc_submissions(id,assignment_id,workspace_id,uploaded_by,title,rights_attested) select s.id,a.id,w.id,u.id,'TEST media',true from f s,f a,f w,f u where s.k='s' and a.k='a' and w.k='w' and u.k='contributor';
insert into storage.objects(bucket_id,name,metadata) select 'runctrl-media',w.id||'/'||u.id||'/'||s.id||'/test.png','{"size":68,"mimetype":"image/png"}'::jsonb from f w,f u,f s where w.k='w' and u.k='contributor' and s.k='s';
insert into rc_assets(id,submission_id,workspace_id,uploader_id,original_name,storage_path,mime_type,bytes) select x.id,s.id,w.id,u.id,'test.png',w.id||'/'||u.id||'/'||s.id||'/test.png','image/png',68 from f x,f s,f w,f u where x.k='x' and s.k='s' and w.k='w' and u.k='contributor';
select pg_temp.ok(exists(select 1 from rc_assets where id=(select id from f where k='x')),'contributor registers private object');
select pg_temp.as_user('editor');
select pg_temp.no($q$update rc_submissions set status='approved' where id=(select id from f where k='s')$q$,'cleared assets','uncleared package approval blocked');
select pg_temp.no($q$update rc_assets set review_status='approved',rights_status='cleared' where id=(select id from f where k='x')$q$,'supporting rights notes','rights clearance needs notes');
update rc_assets set review_status='approved',rights_status='cleared',rights_note='TEST written clearance' where id=(select id from f where k='x');
update rc_submissions set status='approved' where id=(select id from f where k='s');
select pg_temp.ok((select status='approved' from rc_submissions where id=(select id from f where k='s')),'cleared package approval works');
select pg_temp.no($q$update rc_assets set review_status='rejected',rights_status='restricted' where id=(select id from f where k='x')$q$,'Reopen the package','approved assets locked');
select pg_temp.no($q$update rc_submissions set status='published' where id=(select id from f where k='s')$q$,'not enabled','publication disabled');
select pg_temp.as_user('contributor');
select pg_temp.no($q$insert into storage.objects(bucket_id,name) select 'runctrl-media',w.id||'/'||u.id||'/'||s.id||'/late.png' from f w,f u,f s where w.k='w' and u.k='contributor' and s.k='s'$q$,'row-level security','late upload blocked');
select pg_temp.as_user('viewer');
select pg_temp.ok(not exists(select 1 from rc_assignments where id=(select id from f where k='a')),'viewer operational access blocked');
select pg_temp.as_user('owner');
update rc_members set role='viewer' where workspace_id=(select id from f where k='w') and user_id=(select id from f where k='outsider');
select pg_temp.as_user('outsider');
select pg_temp.ok(not exists(select 1 from rc_assignments where id=(select id from f where k='a')),'cross-workspace assignments isolated');
select pg_temp.ok(not exists(select 1 from rc_credentials where id=(select id from f where k='c')),'cross-workspace credentials isolated');
select pg_temp.ok(not exists(select 1 from rc_submissions where id=(select id from f where k='s')),'cross-workspace submissions isolated');
select pg_temp.ok(not exists(select 1 from rc_assets where id=(select id from f where k='x')),'cross-workspace assets isolated');
select pg_temp.ok(not exists(select 1 from storage.objects where bucket_id='runctrl-media' and name like (select id::text||'/%' from f where k='w')),'cross-workspace private files isolated');
select pg_temp.ok(not exists(select 1 from rc_audit where workspace_id=(select id from f where k='w')),'cross-workspace audit isolated');
select pg_temp.as_user('owner');
select pg_temp.no($q$update rc_members set role='viewer' where workspace_id=(select id from f where k='w') and user_id=auth.uid()$q$,'retain an owner','last owner lockout blocked');
select pg_temp.ok(exists(select 1 from rc_audit where workspace_id=(select id from f where k='w') and entity='rc_credentials' and next_status='authorized'),'credential approval audit records actor and transition');
select * from results;
rollback;
